{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "flip",
  "supportive_card_ids": ["C73","C74","C77","C79","C81","C84","C53","C57","C58","C60","C52"],
  "contradictory_card_ids": ["C01","C08","C12","C13","C27","C11","C20","C33","C68","C69","C72"],
  "prediction_basis_card_ids": ["C73","C79","C84","C53","C58","C60"],
  "claims": [
    {
      "claim": "L6 hepatic metabolism records show that the retinoid scaffold (all-trans-retinoic acid) is subject to extensive CYP-mediated 4-hydroxylation/oxidation in human liver microsomes and substantial scaled intrinsic clearance in mice, indicating a hepatic first-pass liability relevant to the query's retinoid amide.",
      "card_ids": ["C73","C79","C81","C84"]
    },
    {
      "claim": "L4 solubility/dissolution records for highly lipophilic carotenoids/retinoids show extremely poor aqueous solubility and dissolution, consistent with the query's logP 6.86 and indicating a solubility-limited absorption liability.",
      "card_ids": ["C53","C57","C58","C60","C52"]
    },
    {
      "claim": "The high-F L1 contexts are structurally distant (small polar phenols or small anilides) or qualitative/food-dependent (zeaxanthin), so they do not provide affirmative evidence that this specific lipophilic retinamide reaches F >= 20%.",
      "card_ids": ["C01","C13","C08","C12","C11"]
    },
    {
      "claim": "L5 no-efflux records address only gut-wall efflux/intestinal metabolism and do not overcome the combined solubility and hepatic first-pass liabilities.",
      "card_ids": ["C68","C69","C72"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "changed",
      "card_ids": ["C73","C74","C77","C79","C81","C84"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query retinamide is supplied.",
    "L6 records are for all-trans-retinoic acid/retinaldehyde, not the amide; transfer depends on whether the amide undergoes analogous CYP-mediated 4-hydroxylation and phase II conjugation.",
    "No query-specific aqueous solubility or dissolution measurement; L4 records are for reference carotenoids/retinoids.",
    "Formulation, fed/fasted status, and dose are unspecified; lipid-based formulation or food could improve absorption.",
    "No matched oral-versus-IV exposure data for the query."
  ],
  "decision_summary": "L6 hepatic clearance/metabolic stability evidence for the retinoid scaffold, together with L4 poor-solubility evidence for highly lipophilic carotenoids/retinoids, affirmatively supports a solubility- and first-pass-limited oral profile for this logP 6.86 retinamide. The high-F L1 contexts are too structurally distant or qualitative to establish F >= 20%, so the prediction is flipped to low with moderate confidence."
}

